CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS users(id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name TEXT NOT NULL, email TEXT UNIQUE NOT NULL, password_hash TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'sales', created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS vendors(id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name TEXT NOT NULL, email TEXT, phone TEXT, tax_id TEXT, status TEXT NOT NULL DEFAULT 'active', created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS products(id UUID PRIMARY KEY DEFAULT gen_random_uuid(), sku TEXT UNIQUE NOT NULL, name TEXT NOT NULL, category TEXT DEFAULT 'General', unit_price NUMERIC(12,2) NOT NULL DEFAULT 0 CHECK(unit_price>=0), stock_qty INTEGER NOT NULL DEFAULT 0 CHECK(stock_qty>=0), reorder_level INTEGER NOT NULL DEFAULT 5, created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS purchase_orders(id UUID PRIMARY KEY DEFAULT gen_random_uuid(), po_number TEXT UNIQUE NOT NULL, vendor_id UUID REFERENCES vendors(id), status TEXT NOT NULL DEFAULT 'draft', total NUMERIC(12,2) NOT NULL DEFAULT 0, created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS purchase_order_items(id UUID PRIMARY KEY DEFAULT gen_random_uuid(), po_id UUID REFERENCES purchase_orders(id) ON DELETE CASCADE, product_id UUID REFERENCES products(id), quantity INTEGER NOT NULL CHECK(quantity>0), unit_price NUMERIC(12,2) NOT NULL CHECK(unit_price>=0));
CREATE TABLE IF NOT EXISTS goods_receipts(id UUID PRIMARY KEY DEFAULT gen_random_uuid(), receipt_number TEXT UNIQUE NOT NULL, po_id UUID REFERENCES purchase_orders(id), received_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS sales_orders(id UUID PRIMARY KEY DEFAULT gen_random_uuid(), order_number TEXT UNIQUE NOT NULL, customer_name TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'draft', total NUMERIC(12,2) NOT NULL DEFAULT 0, created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS sales_order_items(id UUID PRIMARY KEY DEFAULT gen_random_uuid(), order_id UUID REFERENCES sales_orders(id) ON DELETE CASCADE, product_id UUID REFERENCES products(id), quantity INTEGER NOT NULL CHECK(quantity>0), unit_price NUMERIC(12,2) NOT NULL CHECK(unit_price>=0));
CREATE TABLE IF NOT EXISTS invoices(id UUID PRIMARY KEY DEFAULT gen_random_uuid(), invoice_number TEXT UNIQUE NOT NULL, order_id UUID REFERENCES sales_orders(id), customer_name TEXT NOT NULL, amount NUMERIC(12,2) NOT NULL, status TEXT NOT NULL DEFAULT 'unpaid', created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS payments(id UUID PRIMARY KEY DEFAULT gen_random_uuid(), invoice_id UUID REFERENCES invoices(id), amount NUMERIC(12,2) NOT NULL CHECK(amount>0), method TEXT DEFAULT 'bank transfer', paid_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS accounts(id UUID PRIMARY KEY DEFAULT gen_random_uuid(), code TEXT UNIQUE NOT NULL, name TEXT NOT NULL, type TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS journal_entries(id UUID PRIMARY KEY DEFAULT gen_random_uuid(), reference TEXT NOT NULL, description TEXT, debit NUMERIC(12,2) NOT NULL DEFAULT 0, credit NUMERIC(12,2) NOT NULL DEFAULT 0, created_at TIMESTAMPTZ DEFAULT now(), CHECK(debit>=0 AND credit>=0));
CREATE TABLE IF NOT EXISTS approvals(id UUID PRIMARY KEY DEFAULT gen_random_uuid(), entity_type TEXT NOT NULL, entity_id UUID NOT NULL, status TEXT NOT NULL DEFAULT 'pending', approver TEXT, comments TEXT, created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS stock_movements(id UUID PRIMARY KEY DEFAULT gen_random_uuid(), product_id UUID REFERENCES products(id), movement_type TEXT NOT NULL, quantity INTEGER NOT NULL, reference TEXT, created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_logs(id UUID PRIMARY KEY DEFAULT gen_random_uuid(), actor TEXT DEFAULT 'system', action TEXT NOT NULL, entity_type TEXT NOT NULL, entity_id TEXT, details JSONB DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ DEFAULT now());
